using System.Security.Cryptography;
using System.Text;

namespace OllamaRouter.Security;

/// <summary>
/// Cryptographic helpers for the API key system (task #50). Keys are 32 bytes (256 bits)
/// generated by a cryptographically safe RNG (<see cref="RandomNumberGenerator"/>) and encoded
/// as base64url (43 chars, no padding) — the exact same format for the auto-generated default
/// key and every operator-created user key.
/// <para>
/// Validation is FAST-REJECT + constant-time: <see cref="IsValidApiKeyFormat"/> cheaply
/// rejects structurally invalid keys, and the store compares candidate keys with
/// <see cref="CryptographicOperations.FixedTimeEquals"/> only (never <c>string.Equals</c> or
/// dictionary lookups by raw key).
/// </para>
/// </summary>
public static class ApiKeyCrypto
{
    /// <summary>Key material length in bytes (256 bits).</summary>
    public const int KeyByteLength = 32;

    /// <summary>Encoded key length in base64url characters (no padding): ceil(32 / 3) * 4 = 43.</summary>
    public const int EncodedKeyLength = 43;

    /// <summary>
    /// Generates a fresh API key: <see cref="KeyByteLength"/> random bytes encoded as base64url
    /// (<see cref="EncodedKeyLength"/> chars). Never throws on supported platforms.
    /// </summary>
    public static string GenerateKey() => ToBase64Url(RandomNumberGenerator.GetBytes(KeyByteLength));

    /// <summary>
    /// Returns true when <paramref name="key"/> is structurally a valid API key: exactly
    /// <see cref="EncodedKeyLength"/> base64url characters (alphabet <c>[A-Za-z0-9_-]</c>, no
    /// padding, no whitespace) that decode to exactly <see cref="KeyByteLength"/> bytes.
    /// This is a cheap pre-filter — it must NOT be used as the sole validation (it leaks the
    /// key shape into a non-constant-time path); the store additionally applies a
    /// constant-time comparison against the stored key material.
    /// </summary>
    public static bool IsValidApiKeyFormat(string? key)
    {
        if (key is null || key.Length != EncodedKeyLength)
        {
            return false;
        }

        foreach (var c in key)
        {
            var ok = (c is >= 'A' and <= 'Z')
                || (c is >= 'a' and <= 'z')
                || (c is >= '0' and <= '9')
                || c == '-'
                || c == '_';
            if (!ok)
            {
                return false;
            }
        }

        try
        {
            var standardBase64 = key.Replace('-', '+').Replace('_', '/');
            var padding = (4 - (standardBase64.Length % 4)) % 4;
            if (padding > 0)
            {
                standardBase64 += new string('=', padding);
            }

            return Convert.FromBase64String(standardBase64).Length == KeyByteLength;
        }
        catch (FormatException)
        {
            return false;
        }
    }

    /// <summary>
    /// Computes the SHA-256 hash (bytes) of a raw base64url key value (UTF-8 encoded). This is
    /// the ONLY form of a user key ever persisted to <c>config/api-keys.json</c> — the raw key
    /// is returned to the operator exactly once at creation and never written to disk.
    /// </summary>
    public static byte[] HashKey(string key) => SHA256.HashData(Encoding.UTF8.GetBytes(key));

    /// <summary>
    /// Encodes bytes as base64url (RFC 4648 §5, no padding): standard base64 with
    /// <c>+</c> → <c>-</c>, <c>/</c> → <c>_</c> and the trailing <c>=</c> stripped.
    /// </summary>
    public static string ToBase64Url(byte[] bytes)
    {
        ArgumentNullException.ThrowIfNull(bytes);
        var base64 = Convert.ToBase64String(bytes, Base64FormattingOptions.None);
        return base64.TrimEnd('=').Replace('+', '-').Replace('/', '_');
    }
}
